using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using SmartTshwane.Data;using SmartTshwane.Models;
namespace SmartTshwane.Controllers;
[Authorize(Roles="Admin")]public class AdminController(AppDb db):Controller{
public async Task<IActionResult> Index(){ViewBag.Users=await db.Users.CountAsync();ViewBag.Pending=await db.Requests.CountAsync(x=>x.Status=="Pending");ViewBag.Resolved=await db.Requests.CountAsync(x=>x.Status=="Resolved");ViewBag.InProgress=await db.Requests.CountAsync(x=>x.Status=="In Progress");ViewBag.Rejected=await db.Requests.CountAsync(x=>x.Status=="Rejected");return View(await db.Requests.Include(x=>x.Category).Include(x=>x.User).OrderByDescending(x=>x.CreatedUtc).ToListAsync());}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Update(int id,string status,string? note){if(!new[]{"Pending","In Progress","Resolved","Rejected"}.Contains(status))return BadRequest("Invalid status");var r=await db.Requests.FindAsync(id);if(r==null)return NotFound();r.Status=status;r.AdminNote=note?.Trim();db.Notifications.Add(new Notification{UserId=r.UserId,Message=$"Report #TSH-{r.Id} status: {status}. {r.AdminNote}"});await db.SaveChangesAsync();return RedirectToAction("Index");}
public async Task<IActionResult> Manage(){ViewBag.Departments=await db.Departments.OrderBy(x=>x.Name).ToListAsync();ViewBag.Categories=await db.Categories.Include(x=>x.Department).OrderBy(x=>x.Name).ToListAsync();ViewBag.Users=await db.Users.OrderBy(x=>x.FullName).ToListAsync();return View();}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> AddDepartment(string name){if(string.IsNullOrWhiteSpace(name)||name.Length>100)return BadRequest();db.Departments.Add(new Department{Name=name.Trim()});await db.SaveChangesAsync();return RedirectToAction("Manage");}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> AddCategory(string name,int? departmentId){if(string.IsNullOrWhiteSpace(name)||name.Length>100)return BadRequest();if(departmentId.HasValue&&!await db.Departments.AnyAsync(x=>x.Id==departmentId))return BadRequest();db.Categories.Add(new Category{Name=name.Trim(),DepartmentId=departmentId});await db.SaveChangesAsync();return RedirectToAction("Manage");}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> AssignCategory(int id,int? departmentId){var c=await db.Categories.FindAsync(id);if(c==null)return NotFound();if(departmentId.HasValue&&!await db.Departments.AnyAsync(x=>x.Id==departmentId))return BadRequest();c.DepartmentId=departmentId;await db.SaveChangesAsync();return RedirectToAction("Manage");}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> ChangeRole(int id,string role){if(role!="Citizen"&&role!="Admin")return BadRequest();var u=await db.Users.FindAsync(id);if(u==null)return NotFound();if(u.Id.ToString()==User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value&&role!="Admin")return BadRequest("Cannot remove your own admin access.");u.Role=role;await db.SaveChangesAsync();return RedirectToAction("Manage");}
}
